import './_header.scss'
import logo from '../../assets/images/logo.png';

function Header() {
    let element = <><>
        <div id="header">
            <div className="container">
                <div className="header">
                    {/*<h1>A</h1>*/}
                    <img className={foto-one} src={logo} alt=""/>
                    <p>AJONIX</p>

                </div>
            </div>
        </div>
    </>
    </>;
    return element
}



export default Header;
